mapper.update:
UPDATE growth_record
resume_count = #{resumeCount}, interview_count = #{interviewCount}, practice_count = #{practiceCount}, collection_count = #{collectionCount}, continuous_checkin_days = #{continuousCheckinDays}, last_checkin_date = #{lastCheckinDate},
WHERE student_id = #{studentId}

mapper.select:
SELECT COALESCE(
    (
        SELECT COUNT(*) FROM resume_pdf rp WHERE rp.student_id = #{studentId}
    ), 0
)
+ COALESCE(
    (
        SELECT COUNT(*)
        FROM resume r
        INNER JOIN student st ON r.user_id = st.user_id
        WHERE st.student_id = #{studentId}
    ), 0
)
+ COALESCE(
    (
        SELECT COUNT(DISTINCT ac.id)
        FROM ai_consult ac
        INNER JOIN student st ON ac.user_id = st.user_id
        WHERE st.student_id = #{studentId}
          AND IFNULL(TRIM(ac.user_content), '') <> ''
          AND (
              ac.user_content LIKE '%润色简历%'
              OR ac.user_content LIKE '%帮我润色简历%'
              OR ac.user_content LIKE '%简历润色%'
              OR (
                  ac.user_content LIKE '%润色%'
                  AND (ac.user_content LIKE '%简历%' OR ac.user_content LIKE '%经历%')
              )
          )
    ), 0
)

